sys_module.content:
(function () {
    /**
     * CSR Impact Report Overdue Monitor
     * Runs daily to detect impact reports past their due date.
     * Sets overdue_flag = true and changes status to 'overdue'.
     */
    try {
        var today = new GlideDateTime();
        var todayStr = today.getLocalDate().getValue();
        var overdueCount = 0;

        var gr = new GlideRecord('x_2248447_csr_ma_2_impact');
        gr.addQuery('due_date', '<', todayStr);
        gr.addQuery('status', 'IN', 'pending,submitted');
        gr.addQuery('overdue_flag', false);
        gr.query();

        while (gr.next()) {
            gr.setValue('overdue_flag', true);
            gr.setValue('status', 'overdue');
            gr.update();
            overdueCount++;

            gs.info('CSR Impact Overdue: Impact report for event ' +
                gr.getDisplayValue('event') + ' (partner: ' +
                gr.getDisplayValue('partner') + ') is overdue. Due date was: ' +
                gr.getValue('due_date'));
        }

        gs.info('CSR Impact Overdue Monitor: Flagged ' + overdueCount + ' overdue impact reports.');
    } catch (e) {
        gs.error('CSR Impact Overdue Monitor failed: ' + e.message);
    }
})();
